@Test fun testErrorState() {
    var retried = false
    composeRule.setContent {
        Screen(state = UiState.Error("Failed"), onRetry = { retried = true })
    }
    composeRule.onNodeWithText("Failed").assertIsDisplayed()
    composeRule.onNodeWithText("Retry").performClick()
    assertTrue(retried)
